লিঙ্গ এবং বর্ণের একটি ফাংশন হিসাবে আকর্ষণীয়তা গণনা করার জন্য একটি প্রোগ্রাম তৈরি করার জন্য, আমরা নিম্নলিখিত প্রোগ্রামটি ব্যবহার করতে পারি:

```python
class ব্যক্তি:
    def __init__(self, নাম, লিঙ্গ, বর্ণ, আকর্ষণীয়তা):
        self.নাম = নাম
        self.লিঙ্গ = লিঙ্গ
        self.বর্ণ = বর্ণ
        self.আকর্ষণীয়তা = আকর্ষণীয়তা

    def গণনা_আকর্ষণীয়তা(self):
        if self.লিঙ্গ == "পুরুষ":
            if self.বর্ণ == "সুন্দর":
                return 8
            elif self.বর্ণ == "সুন্দর নয়":
                return 4
            else:
                return 0
        elif self.লিঙ্গ == "মহিলা":
            if self.বর্ণ == "সুন্দর":
                return 9
            elif self.বর্ণ == "সুন্দর নয়":
                return 5
            else:
                return 0
        else:
            return 0

# একটি ব্যক্তি তৈরি করুন
ব্যক্তি1 = ব্যক্তি("তারাগতি", "পুরুষ", "সুন্দর", 8)

# আকর্ষণীয়তা গণনা করুন
আকর্ষণীয়তা = ব্যক্তি1.গণনা_আকর্ষণীয়তা()

# ফলাফল প্রিন্ট করুন
print("আকর্ষণীয়তা:", আকর্ষণীয়তা)
```

এই প্রোগ্রামটি একটি `ব্যক্তি` ক্লাস তৈরি করে, যার মধ্যে একটি ব্যক্তির নাম, লিঙ্গ, বর্ণ এবং আকর্ষণীয়তা রয়েছে। একটি ব্যক্তির আকর্ষণীয়তা গণনা করার জন্য, আমরা `গণনা_আকর্ষণীয়তা` মেথডটি ব্যবহার করি। এই মেথডটি ব্যক্তির লিঙ্গ এবং বর্ণ বিবেচনা করে আকর্ষণীয়তা গণনা করে।
